\begin{abstract}
Let $2^{[n]}$ denote the lattice of subsets of $[n]=\{1,\dots,n\}$ ordered by inclusion. For a finite poset $P$, a family $\mathcal F\subseteq 2^{[n]}$ is \emph{weak $P$-free} if it contains no injective order-preserving image of $P$ (extra containments being permitted), and \emph{strong $P$-free} if it contains no induced such image; the extremal numbers are $\La(n,P)\le\LaS(n,P)$. We prove: (i) the weak/strong gap is unbounded, since $\La(n,A_{m+1})=m$ for the $m$-element antichain while $\LaS(n,A_2)=n+1$; (ii) $\LaS(n,A_3)=2n$, i.e.\ a family of subsets of $[n]$ with no three pairwise incomparable members has at most $2n$ sets, attained by an explicit disjoint union of two chains, with no appeal to Dilworth's or Greene--Kleitman theory; (iii) a fractional-knapsack inequality converting Lubell weight to cardinality without loss, giving Erd\H{o}s' $k$-Sperner theorem and the exact chain values $\La(n,C_{k+1})=\LaS(n,C_{k+1})=\Sigma(n,k)$, the sum of the $k$ largest binomial coefficients; (iv) the two-sided bracket $\Sigma(n,h(P)-1)\le\La(n,P)\le\Sigma(n,|P|-1)$ for arbitrary finite $P$, which strictly improves the classical bound $(|P|-1)\binom{n}{\lfloor n/2\rfloor}$ (for instance $\La(10,B_3)\le 1002$ rather than $1764$); and (v) a rank-rigidity principle showing that if $P$ contains a \emph{tall butterfly of height $m$} then $m+2$ consecutive layers of $2^{[n]}$ are weak $P$-free, so the height lower bound of the bracket is not tight. The diamond $B_2$ contains no butterfly, which isolates precisely why the diamond problem resists this method.
\end{abstract}

\section{Introduction}

\subsection{The forbidden-subposet problem}

Sperner's theorem (1928) states that a family of subsets of $[n]$ in which no member contains another has at most $\binom{n}{\ffloor{n/2}}$ members, with equality for a middle layer. Erd\H{o}s (1945) extended this to families with no chain of $k+1$ members, showing that the maximum is the total size of the $k$ largest layers. Both are instances of the \emph{forbidden-subposet problem}: given a finite poset $P$, determine the largest family $\mathcal F\subseteq 2^{[n]}$ containing no copy of $P$. The problem is solved for chains and a handful of small posets; even the four-element diamond is open. This paper contributes exact values, a systematic sharpening of the standard upper bound, a general two-sided bracket, and a structural obstruction explaining the lossiness of the standard lower bound.

\subsection{Two notions of containment}

\begin{definition}[weak and strong copies]
Let $P$ be a finite poset and $\mathcal F\subseteq 2^{[n]}$. A map $\iota:P\to 2^{[n]}$ is a
\begin{itemize}
\item \textbf{weak copy} of $P$ if $\iota$ is injective and $p<q \implies \iota(p)\subsetneq\iota(q)$;
\item \textbf{strong copy} (or \emph{induced copy}) if $\iota$ is injective and $\iota(p)\subsetneq\iota(q)\iff p<q$.
\end{itemize}
The copy \emph{lies in} $\mathcal F$ if $\iota(p)\in\mathcal F$ for all $p$. The family $\mathcal F$ is \textbf{weak $P$-free} (resp.\ \textbf{strong $P$-free}) if no weak (resp.\ strong) copy of $P$ lies in $\mathcal F$.
\end{definition}

\begin{definition}
$\La(n,P)=\max\{|\mathcal F| : \mathcal F\subseteq 2^{[n]}\text{ weak } P\text{-free}\}$ and
$\LaS(n,P)=\max\{|\mathcal F| : \mathcal F\subseteq 2^{[n]}\text{ strong } P\text{-free}\}$.
\end{definition}

Every strong copy is a weak copy, hence weak $P$-freeness implies strong $P$-freeness and
\begin{equation}\label{eq:LaLeLaS}
\La(n,P)\;\le\;\LaS(n,P).
\end{equation}

\subsection{Notation}

Layer $i$ is $\Lambda_i=\{A\subseteq[n]:|A|=i\}$, of size $\binom{n}{i}$. For $a,k\ge 0$ the \textbf{window family} is
\[
\mathcal L(a,k)=\{A\subseteq[n]: a\le |A| < a+k\},\qquad |\mathcal L(a,k)|=\sum_{i=a}^{a+k-1}\binom{n}{i}.
\]
The \textbf{central start} is $c(n,k)=\lceil (n-k)/2\rceil$, so that $n\le 2c(n,k)+k\le n+1$, and
\[
\Sigma(n,k)=\sum_{i=c(n,k)}^{c(n,k)+k-1}\binom{n}{i}
\]
is the total size of the $k$ \textbf{central layers}.

\begin{lemma}[the central window is optimal]\label{lem:window}
Let $k\le n+1$. Then $\binom{n}{i}\le\binom{n}{w}$ for every $i$ outside the window $[c(n,k),c(n,k)+k)$ and every $w$ inside it. Consequently $\Sigma(n,k)$ is the sum of the $k$ largest binomial coefficients in row $n$.
\end{lemma}

\begin{proof}[Proof sketch]
The binomial row is unimodal and symmetric: $\binom{n}{i}\le\binom{n}{j}$ whenever $i<j$ and $i+j\le n$, and whenever $i>j$ and $i+j\ge n$. If $i$ lies below the window and $w$ inside, then $i<w$ and $i+w\le 2c+k-1\le n$; if $i$ lies above, then $i>w$ and $i+w\ge 2c+k\ge n$.
\end{proof}

Throughout, $A_m$ is the $m$-element antichain, $B_d$ the Boolean lattice of all $2^d$ subsets of a $d$-set, $C_k$ the chain with $k$ elements, and $h(P)$ the height of $P$ (the maximum number of elements of a chain in $P$).

\section{The weak/strong gap}

\begin{theorem}[weak antichain-freeness is a cardinality condition]\label{thm:weakanti}
For every $m$ and every family $\mathcal F$: $\mathcal F$ is weak $A_m$-free if and only if $|\mathcal F|<m$.
\end{theorem}

\begin{proof}[Proof sketch]
A weak copy of $A_m$ imposes no containment requirement, so it is precisely an injection $A_m\hookrightarrow\mathcal F$; such an injection exists iff $|\mathcal F|\ge m$.
\end{proof}

\begin{corollary}
If $m\le 2^n$ then $\La(n,A_{m+1})=m$; in particular $\La(n,A_2)=1$.
\end{corollary}

\begin{theorem}[strong $A_2$-freeness is chain-ness]
$\mathcal F$ is strong $A_2$-free if and only if $\mathcal F$ is a chain: $A\subseteq B$ or $B\subseteq A$ for all $A,B\in\mathcal F$.
\end{theorem}

\begin{proof}[Proof sketch]
A strong copy of $A_2$ is an ordered pair of distinct \emph{incomparable} sets; its absence is exactly the chain condition.
\end{proof}

\begin{theorem}\label{thm:LaS2}
$\LaS(n,A_2)=n+1$.
\end{theorem}

\begin{proof}[Proof sketch]
Upper bound: distinct members of a chain have distinct cardinalities, and cardinalities lie in $\{0,\dots,n\}$. Lower bound: the initial segments $S_i=\{1,\dots,i\}$, $0\le i\le n$, form a chain of $n+1$ sets.
\end{proof}

\begin{corollary}[unbounded gap]
For $n\ge 1$: $\La(n,A_2)=1<n+1=\LaS(n,A_2)$, with $\LaS(n,A_2)-\La(n,A_2)=n$ and $\LaS(n,A_2)=(n+1)\La(n,A_2)$. Hence \eqref{eq:LaLeLaS} is never an equality for $A_2$, and no bound $\LaS\le c\cdot\La$ can hold with $c$ independent of $n$.
\end{corollary}

\section{The three-element antichain: $\LaS(n,A_3)=2n$}

Strong $A_3$-freeness means \emph{no three pairwise incomparable sets}. By Dilworth's theorem such a family is a union of two chains, and the Greene--Kleitman philosophy predicts the optimum $(n+1)+(n-1)=2n$, the total length of the two longest chains of a symmetric chain decomposition. We prove this directly, using neither theorem.

\subsection{The layer bound}

\begin{lemma}[layer bound]\label{lem:layer}
If $\mathcal F$ is strong $A_m$-free then $|\{A\in\mathcal F:|A|=i\}|<m$ for every $i$.
\end{lemma}

\begin{proof}[Proof sketch]
Distinct sets of equal cardinality are incomparable, since strict inclusion strictly increases cardinality. Hence $m$ members of a common size would carry a strong copy of $A_m$: both sides of the equivalence $\iota(p)\subsetneq\iota(q)\iff p<q$ are false for all pairs.
\end{proof}

\begin{lemma}[extreme layers]\label{lem:extreme}
$|\{A\in\mathcal F:|A|=0\}|\le 1$ and $|\{A\in\mathcal F:|A|=n\}|\le 1$, since $\emptyset$ and $[n]$ are the unique sets of those sizes.
\end{lemma}

\begin{lemma}[general antichain bound]\label{lem:genanti}
$\displaystyle \LaS(n,A_m)\le\sum_{i=0}^{n}\min\!\left(m-1,\binom{n}{i}\right).$
\end{lemma}

\begin{proof}[Proof sketch]
Partition by cardinality; each fibre has at most $m-1$ members by Lemma~\ref{lem:layer} and at most $\binom{n}{i}$ trivially.
\end{proof}

\begin{proposition}[upper bound]\label{prop:upper3}
For $n\ge 1$, every strong $A_3$-free family $\mathcal F\subseteq 2^{[n]}$ satisfies $|\mathcal F|\le 2n$.
\end{proposition}

\begin{proof}[Proof sketch]
With $f(i)=|\{A\in\mathcal F:|A|=i\}|$ we have $|\mathcal F|=\sum_{i=0}^n f(i)$, $f(i)\le 2$ by Lemma~\ref{lem:layer}, and $f(0),f(n)\le 1$ by Lemma~\ref{lem:extreme}; hence $|\mathcal F|\le 1+2(n-1)+1=2n$.
\end{proof}

\subsection{The extremal construction}

Fix the natural ordering of $[n]$ and set $S_i=\{1,\dots,i\}$ for $0\le i\le n$.

\begin{definition}
The \textbf{initial-segment family} is $\mathcal I=\{S_0,\dots,S_n\}$; the \textbf{complemented family} is $\mathcal I^{\mathrm c}=\{\overline{S_i} : 1\le i\le n-1\}$, the complements of the proper nonempty initial segments.
\end{definition}

\begin{lemma}
$\mathcal I$ is a chain with $|\mathcal I|=n+1$, and $\mathcal I^{\mathrm c}$ is a chain with $|\mathcal I^{\mathrm c}|=n-1$.
\end{lemma}

\begin{proof}[Proof sketch]
$S_i\subsetneq S_j$ for $i<j\le n$ because $i+1\in S_j\setminus S_i$; complementation reverses inclusion and preserves distinctness.
\end{proof}

\begin{lemma}[disjointness]\label{lem:disj}
$\mathcal I\cap\mathcal I^{\mathrm c}=\emptyset$.
\end{lemma}

\begin{proof}[Proof sketch]
Every nonempty initial segment contains $1$, whereas no $\overline{S_i}$ with $i\ge 1$ does; and $\overline{S_i}\ne\emptyset$ because $i\le n-1$.
\end{proof}

\begin{lemma}[a union of two chains is strong $A_3$-free]\label{lem:twochains}
If $\mathcal C_1,\mathcal C_2$ are chains, then $\mathcal C_1\cup\mathcal C_2$ contains no three pairwise incomparable sets.
\end{lemma}

\begin{proof}[Proof sketch]
Three distinct sets in two chains contain, by pigeonhole, two lying in the same chain; those two are strictly comparable, so no strong copy of $A_3$ can exist.
\end{proof}

\begin{theorem}[main result]\label{thm:main3}
For every $n\ge 1$, $\LaS(n,A_3)=2n$.
\end{theorem}

\begin{proof}[Proof sketch]
The upper bound is Proposition~\ref{prop:upper3}. For the lower bound, $\mathcal I\cup\mathcal I^{\mathrm c}$ is strong $A_3$-free by Lemma~\ref{lem:twochains} and has $(n+1)+(n-1)=2n$ members by Lemma~\ref{lem:disj}.
\end{proof}

\begin{corollary}[Greene--Kleitman prediction, first two cases]
$\LaS(n,A_3)=\LaS(n,A_2)+(n-1)$. Both values agree with the prediction $\LaS(n,A_m)\stackrel{?}{=}\sum_{i=0}^{m-2}(n+1-2i)$ obtained from the $m-1$ longest chains of a symmetric chain decomposition: $n+1$ for $m=2$, $2n$ for $m=3$.
\end{corollary}

\begin{remark}
For $m\ge 4$ the bound of Lemma~\ref{lem:genanti} is $(m-1)(n+1)-O_m(1)$, whereas the conjectured value is $(m-1)(n+1)-(m-1)(m-2)$: the layer bound sees the thinness of the two extreme layers but not of the near-extreme ones.
\end{remark}

\section{The Lubell function and Erd\H{o}s' $k$-Sperner theorem}

\begin{definition}[Lubell function]
For $\mathcal F\subseteq 2^{[n]}$, $\displaystyle \lambda(\mathcal F)=\sum_{A\in\mathcal F}\binom{n}{|A|}^{-1}$.
\end{definition}

A uniformly random maximal chain $\emptyset=X_0\subsetneq\cdots\subsetneq X_n=[n]$ passes through a given $A$ with probability $\binom{n}{|A|}^{-1}$, so
\begin{equation}\label{eq:prob}
\lambda(\mathcal F)=\mathbb E\big[\#\{\text{members of }\mathcal F\text{ on a random maximal chain}\}\big].
\end{equation}

\begin{theorem}[LYM inequality]\label{thm:lym}
If $\mathcal F$ is an antichain then $\lambda(\mathcal F)\le 1$.
\end{theorem}

\begin{proof}[Proof sketch]
Immediate from \eqref{eq:prob}: a chain meets an antichain at most once.
\end{proof}

\begin{theorem}[Mirsky peeling]\label{thm:mirsky}
If $\mathcal F$ contains no chain of $k+1$ members then $\lambda(\mathcal F)\le k$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $k$; for $k=0$ the family is empty. Let $M$ be the set of maximal members of $\mathcal F$, an antichain, so $\lambda(M)\le1$ by Theorem~\ref{thm:lym}. Any chain of $k$ sets in $\mathcal F\setminus M$ extends upward to a chain of $k+1$ sets in $\mathcal F$, so $\mathcal F\setminus M$ has no chain of $k$ sets and $\lambda(\mathcal F\setminus M)\le k-1$ by induction. Add the two.
\end{proof}

\begin{theorem}[fractional knapsack inequality]\label{thm:knap}
Let $C_0,\dots,C_{N-1}>0$ and $0\le m_i\le C_i$. Let $W\subseteq\{0,\dots,N-1\}$ with $|W|=k$, and suppose $c>0$ satisfies $C_i\ge c$ for $i\in W$ and $C_i\le c$ for $i\notin W$. If $\sum_{i<N}m_i/C_i\le k$, then $\sum_{i<N}m_i\le\sum_{i\in W}C_i$.
\end{theorem}

\begin{proof}[Proof sketch]
For each $i$,
\[
m_i - c\,\frac{m_i}{C_i}=m_i\left(1-\frac{c}{C_i}\right)\le
\begin{cases}
C_i-c, & i\in W \quad (\text{factor}\ge0,\ m_i\le C_i),\\
0, & i\notin W \quad (\text{factor}\le0,\ m_i\ge0).
\end{cases}
\]
Summing gives $\sum_i m_i - c\sum_i m_i/C_i\le\sum_{i\in W}C_i-ck$; add $c\sum_i m_i/C_i\le ck$.
\end{proof}

\begin{theorem}[knapsack step]\label{thm:knapstep}
Let $k\le n+1$ and $\lambda(\mathcal F)\le k$. Then $|\mathcal F|\le\Sigma(n,k)$.
\end{theorem}

\begin{proof}[Proof sketch]
For $k=0$ the family is empty. Otherwise apply Theorem~\ref{thm:knap} with $N=n+1$, $C_i=\binom{n}{i}$, $m_i=|\{A\in\mathcal F:|A|=i\}|$, $W=[c(n,k),c(n,k)+k)$ and $c=\min_{w\in W}\binom{n}{w}$; Lemma~\ref{lem:window} supplies $C_i\le c$ outside $W$. Fibrewise decomposition gives $|\mathcal F|=\sum_i m_i$ and $\lambda(\mathcal F)=\sum_i m_i/C_i$.
\end{proof}

\begin{theorem}[Erd\H{o}s' $k$-Sperner theorem]\label{thm:erdos}
For $k\le n+1$, a family with no chain of $k+1$ members has at most $\Sigma(n,k)$ members. For $k=1$ this is Sperner's theorem.
\end{theorem}

\begin{lemma}\label{lem:chainfree}
For every $k$ and family $\mathcal F$ the following are equivalent: (i) $\mathcal F$ is weak $C_k$-free; (ii) $\mathcal F$ is strong $C_k$-free; (iii) $\mathcal F$ contains no chain of $k$ sets.
\end{lemma}

\begin{proof}[Proof sketch]
A weak copy of $C_k$ is a strictly increasing sequence of $k$ sets; conversely such a sequence is automatically \emph{induced}, since in a linear order $\iota(p)\subsetneq\iota(q)$ forces $p<q$ by trichotomy and antisymmetry.
\end{proof}

\begin{theorem}[exact chain values]\label{thm:chainexact}
For $k\le n+1$, $\La(n,C_{k+1})=\LaS(n,C_{k+1})=\Sigma(n,k)$.
\end{theorem}

\begin{proof}[Proof sketch]
Upper bounds: Lemma~\ref{lem:chainfree} with Theorem~\ref{thm:erdos}. Lower bound: the window family $\mathcal L(c(n,k),k)$ lies in $k$ layers, hence has no chain of $k+1$ sets, and has $\Sigma(n,k)$ members.
\end{proof}

\section{A two-sided bracket for an arbitrary finite poset}

\begin{lemma}[weak copies preserve chains]\label{lem:preserve}
If $\iota$ is a weak copy of $P$ in $\mathcal F$ and $c_1<\cdots<c_k$ is a chain in $P$, then $\iota(c_1)\subsetneq\cdots\subsetneq\iota(c_k)$ is a chain of $k$ sets in $\mathcal F$.
\end{lemma}

\begin{corollary}[height lower bound]\label{cor:heightlb}
If $P$ has a chain of $k+1$ elements and $\mathcal F$ has no chain of $k+1$ sets, then $\mathcal F$ is weak $P$-free. Hence $\Sigma(n,h(P)-1)\le\La(n,P)$, witnessed by the $h(P)-1$ central layers.
\end{corollary}

\begin{theorem}[Szpilrajn, quantitative form]\label{thm:szpilrajn}
Every finite poset $P$ admits an injective, strictly monotone map $P\to C_{|P|}$.
\end{theorem}

\begin{proof}[Proof sketch]
Extend the order of $P$ to a linear order and sort; the identity map into the linear extension is injective and strictly monotone.
\end{proof}

\begin{corollary}[size upper bound]\label{cor:sizeub}
A weak $P$-free family has no chain of $|P|$ sets; hence if $|P|-1\le n+1$ then $\La(n,P)\le\Sigma(n,|P|-1)$.
\end{corollary}

\begin{proof}[Proof sketch]
Given a chain $X_1\subsetneq\cdots\subsetneq X_{|P|}$ in $\mathcal F$ and the embedding $e$ of Theorem~\ref{thm:szpilrajn}, the map $p\mapsto X_{e(p)}$ is a weak copy of $P$. Apply Theorem~\ref{thm:erdos} with $k=|P|-1$.
\end{proof}

\begin{theorem}[the poset bracket]\label{thm:bracket}
For every finite nonempty poset $P$ with $|P|-1\le n+1$,
\[
\Sigma\big(n,h(P)-1\big)\;\le\;\La(n,P)\;\le\;\Sigma\big(n,|P|-1\big).
\]
Both bounds are exact chain-poset extremal numbers; they coincide iff $h(P)=|P|$, i.e.\ exactly when $P$ is a chain, in which case Theorem~\ref{thm:chainexact} determines $\La(n,P)=\LaS(n,P)$.
\end{theorem}

\subsection{The sharpening is strict}

\begin{lemma}[strict unimodality]\label{lem:unimodal}
If $2k+1<n$ then $\binom{n}{k}<\binom{n}{k+1}$.
\end{lemma}

\begin{proof}[Proof sketch]
From $\binom{n}{k+1}(k+1)=\binom{n}{k}(n-k)$ and $n-k\ge k+2>k+1$.
\end{proof}

\begin{theorem}[strict improvement]\label{thm:strict}
For $3\le k\le n+1$, $\Sigma(n,k)<k\binom{n}{\ffloor{n/2}}$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $a=c(n,k)$. Since $k\ge3$ and $2a+k\le n+1$ we get $2a+1<n$, so $\binom{n}{a}<\binom{n}{\ffloor{n/2}}$ by Lemma~\ref{lem:unimodal} and unimodality; bound the other $k-1$ terms by $\binom{n}{\ffloor{n/2}}$.
\end{proof}

\begin{corollary}
For $d\ge2$ with $2^d-1\le n+1$, $\Sigma(n,d)\le\La(n,B_d)\le\Sigma(n,2^d-1)<(2^d-1)\binom{n}{\ffloor{n/2}}$.
\end{corollary}

\begin{example}
For $d=3$, $n=10$: $c(10,7)=2$, so
\[
\La(10,B_3)\le\binom{10}{2}+\cdots+\binom{10}{8}=45+120+210+252+210+120+45=1002,
\]
whereas the classical bound gives $7\binom{10}{5}=1764$, an improvement of $43\%$. From below, $\Sigma(10,3)=210+252+210=672$.
\end{example}

\section{The butterfly obstruction}

\begin{definition}[butterfly]
A poset $P$ \textbf{contains a butterfly} if there are $p_1\ne p_2$ and $q_1\ne q_2$ in $P$ with $p_i<q_j$ for all $i,j\in\{1,2\}$; equivalently, some two distinct elements have two distinct common strict upper bounds. The \textbf{butterfly poset} $\Bf$ has four elements $a_1,a_2,b_1,b_2$ with $a_i<b_j$ and no other relations; $|\Bf|=4$ and $h(\Bf)=2$.
\end{definition}

\begin{lemma}\label{lem:union}
If $X\ne Y$ are finite sets with $|X|=|Y|$ then $|X|<|X\cup Y|$.
\end{lemma}

\begin{proof}[Proof sketch]
If $|X\cup Y|\le|X|$ then $X=X\cup Y\supseteq Y$, and equal cardinalities force $Y=X$.
\end{proof}

\begin{theorem}[two-layer rigidity]\label{thm:twolayer}
If $P$ contains a butterfly, then $\mathcal L(a,2)$ is weak $P$-free for every $a$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $\iota$ be a weak copy of $P$ inside $\mathcal L(a,2)$ and let $p_1,p_2,q_1,q_2$ witness the butterfly. Only sizes $a$ and $a+1$ occur, and $p_i<q_j$ forces $|\iota(p_i)|<|\iota(q_j)|$; hence $|\iota(p_1)|=|\iota(p_2)|=a$ and $|\iota(q_1)|=|\iota(q_2)|=a+1$. By injectivity and Lemma~\ref{lem:union}, $|\iota(p_1)\cup\iota(p_2)|\ge a+1$. Each $\iota(q_j)$ contains that union and has size $a+1$, so $\iota(q_1)=\iota(p_1)\cup\iota(p_2)=\iota(q_2)$, contradicting injectivity.
\end{proof}

\begin{corollary}
If $P$ contains a butterfly then $\Sigma(n,2)\le\La(n,P)$, regardless of $h(P)$.
\end{corollary}

\begin{theorem}[the height bound is not tight]
For the butterfly poset and every $n\ge1$,
\[
\Sigma(n,1)<\Sigma(n,2)\le\La(n,\Bf)\le\Sigma(n,3),
\]
while Corollary~\ref{cor:heightlb} supplies only $\Sigma(n,h(\Bf)-1)=\Sigma(n,1)$.
\end{theorem}

\begin{proposition}[the diamond escapes]
The diamond $B_2$ does \emph{not} contain a butterfly: any two distinct elements of $B_2$ have at most one common strict upper bound. Hence two-layer freeness for $B_2$ cannot be derived from Theorem~\ref{thm:twolayer}, and the diamond problem requires a different mechanism. By contrast $B_3$ contains a butterfly, e.g.\ $p_1=\emptyset$, $p_2=\{1\}$, $q_1=\{1,2\}$, $q_2=\{1,2,3\}$.
\end{proposition}

\subsection{Rank rigidity and tall butterflies}

\begin{theorem}[rank rigidity]\label{thm:rank}
Let $X_0\subsetneq\cdots\subsetneq X_{L-1}$ be a chain of $L$ sets with $a\le|X_i|<a+L$ for all $i$. Then $|X_i|=a+i$ for every $i$.
\end{theorem}

\begin{proof}[Proof sketch]
Strict inclusion strictly increases cardinality, so $|X_i|\ge a+i$; the same estimate applied to the reversed chain, measured downward from the top of the window, gives $|X_i|\le (a+L-1)-(L-1-i)=a+i$.
\end{proof}

\begin{definition}[tall butterfly]
$P$ has a \textbf{tall butterfly of height $m$} if there are $p_1\ne p_2$, $q_1\ne q_2$ with $p_i<q_j$ for all $i,j$, and chains of $m+1$ elements of $P$ with top elements $p_1$ and $p_2$ respectively. A tall butterfly of height $0$ is exactly a butterfly.
\end{definition}

\begin{theorem}[tall butterfly obstruction]\label{thm:tall}
If $P$ has a tall butterfly of height $m$ then $\mathcal L(a,m+2)$ is weak $P$-free for every $a$; consequently $\Sigma(n,m+2)\le\La(n,P)$.
\end{theorem}

\begin{proof}[Proof sketch]
Appending $q_j$ on top of the chain ending at $p_i$ yields a chain of $m+2$ elements of $P$, whose image is a chain of $m+2$ sets inside $m+2$ consecutive layers. Theorem~\ref{thm:rank} pins the cardinalities: $|\iota(p_i)|=a+m$ and $|\iota(q_j)|=a+m+1$. The argument of Theorem~\ref{thm:twolayer} then applies verbatim.
\end{proof}

\begin{corollary}[unification]
$m=0$ recovers Theorem~\ref{thm:twolayer}. $m=1$ with $P=B_3$ --- witnessed by the chains $\emptyset\subset\{1\}$ and $\emptyset\subset\{2\}$ below the distinct elements $\{1,2\}$ and $\{1,2,3\}$ --- recovers the statement that three consecutive layers of $2^{[n]}$ are weak $B_3$-free.
\end{corollary}

\section{Algorithms}

\begin{algorithmbox}[central window and $\Sigma(n,k)$]
Given $n$ and $k\le n+1$, return $a=\lceil (n-k)/2\rceil$ and $\Sigma(n,k)=\sum_{i=a}^{a+k-1}\binom{n}{i}$. Cost: $O(k)$ arithmetic operations using $\binom{n}{i+1}=\binom{n}{i}(n-i)/(i+1)$.
\end{algorithmbox}

\begin{algorithmbox}[poset bracket]
Given the comparability relation of a poset on $N$ elements: compute $h(P)$ by longest-path dynamic programming on the strict-order DAG in $O(N^2)$; detect a butterfly by scanning all pairs and testing whether their common strict upper set has at least two elements, in $O(N^3)$; compute the largest $m$ admitting a tall butterfly by combining the scan with the longest downward chain terminating at each element. Output
\[
\Big[\ \Sigma\big(n,\max\{h(P)-1,\ m+2\}\big),\ \ \Sigma\big(n,N-1\big)\ \Big].
\]
\end{algorithmbox}

\begin{algorithmbox}[Lubell certificate]
Compute $\lambda(\mathcal F)$ in $O(|\mathcal F|)$ time. If $\lambda(\mathcal F)\le k$ then $|\mathcal F|\le\Sigma(n,k)$ by Theorem~\ref{thm:knapstep}; the converse fails, so $\lambda$ is a certificate, not a characterization. Iterated peeling of maximal elements computes the height of $\mathcal F$.
\end{algorithmbox}

\begin{algorithmbox}[exhaustive verification of $\LaS(n,A_3)$]
Depth-first search over $2^{[n]}$ in a fixed order, maintaining the incomparable pairs already chosen; a candidate may be added unless it is incomparable to both members of some chosen incomparable pair. Branch-and-bound on ``current size $+$ remaining candidates $\le$ best known'' confirms the optimum $2n$ for $n\le5$ in well under a second.
\end{algorithmbox}

\section{Discussion}

\subsection{What makes weight work, and where it stops}

The Lubell function converts counting into a probability computation \eqref{eq:prob}, which is why the chain problem is soluble: every antichain contributes at most $1$, so the height of a family controls its weight, and Theorem~\ref{thm:knap} converts weight to cardinality without loss --- tightly, since the central window achieves both the weight $k$ and the cardinality $\Sigma(n,k)$.

The limitation is equally sharp. The family $\mathcal G=\{\emptyset\}\cup\Lambda_1\cup\{[n]\}$ is butterfly-free for $n\ge3$ (any two distinct members have $[n]$ as their unique common strict upper bound inside $\mathcal G$), yet $\lambda(\mathcal G)=1+n\cdot\frac1n+1=3$. So no bound ``butterfly-free $\Rightarrow\lambda\le2$'' exists, and Conjecture~\ref{conj:butterfly} below is genuinely a cardinality, not a weight, statement.

\subsection{Weak versus strong}

For patterns with rich order structure --- chains, Boolean lattices --- the weak and strong extremal numbers can coincide (Theorem~\ref{thm:chainexact}). For antichains they diverge maximally: the weak invariant degenerates to a cardinality condition, while the strong invariant becomes the Dilworth-type question ``how large can a family of width $<m$ be?''. The exact answers $n+1$ and $2n$ for widths $1$ and $2$ are the first two terms of the Greene--Kleitman prediction, and the extremal families --- one chain, then two disjoint chains --- are the first two steps of a symmetric chain decomposition.

\subsection{One local obstruction, many layer theorems}

The tall butterfly is a single local configuration implying all the ``consecutive layers are $P$-free'' statements considered here, via rank rigidity: within a window of $L$ layers a chain of $L$ sets has no freedom, and the cardinality constraints force distinct elements to map to the same union. That $B_2$ evades this obstruction is not an accident of the proof: in $B_2$, two elements never have two distinct common strict upper bounds.

\section{Future directions}

\begin{conjecture}[diamond]\label{conj:diamond}
$\La(n,B_2)=\binom{n}{\ffloor{n/2}}+\binom{n}{\ffloor{n/2}+1}$ for all $n\ge1$.
\end{conjecture}

The bracket gives $\Sigma(n,2)\le\La(n,B_2)\le\Sigma(n,3)$, and exhaustive search confirms the lower end for $n=3,4$. The upper bound loses a whole layer because it uses only the height of a weak copy (a $4$-chain) and never the \emph{branching} of the diamond; a Lubell-function argument charging the branching should remove the third layer. Since the knapsack step converts any improved bound $\lambda(\mathcal F)\le 2+o(1)$ for diamond-free $\mathcal F$ immediately into the cardinality statement, only the local analysis remains.

\begin{conjecture}[butterfly]\label{conj:butterfly}
$\La(n,\Bf)=\Sigma(n,2)$, the sum of the two largest binomial coefficients, for $n\ge3$.
\end{conjecture}

We have $\Sigma(n,2)\le\La(n,\Bf)\le\Sigma(n,3)$. The key insight is the rigidity behind Theorem~\ref{thm:twolayer}: in a butterfly-free family, any two sets have at most one common strict upper bound in the family, so the ``upper shadow'' map from pairs to upper sets is injective --- a counting statement that should close the remaining layer.

\begin{conjecture}[the layer number is the tall-butterfly invariant]
For a finite poset $P$ let $e(P)$ be the largest $k$ such that $k$ consecutive layers of $2^{[n]}$ are weak $P$-free for all $n$ and all starting levels. We proved $e(P)\ge m+2$ whenever $P$ has a tall butterfly of height $m$, and $e(P)\ge h(P)-1$ always. \textbf{Conjecture:} $e(P)$ equals $1$ plus the largest $m+1$ over all tall butterflies of height $m$ in $P$; that is, the tall-butterfly obstruction is the only obstruction.
\end{conjecture}

\paragraph{Further problems.}
\begin{itemize}
\item \emph{General antichains.} Determine $\LaS(n,A_m)$ for $m\ge4$; the conjectured value $\sum_{i<m-1}(n+1-2i)$ is attained by the $m-1$ longest chains of a symmetric chain decomposition, but the layer bound of Lemma~\ref{lem:genanti} is not tight there.
\item \emph{Strong Boolean patterns.} Is $\LaS(n,B_d)$ ever strictly larger than $\La(n,B_d)$ for $d\ge2$ and large $n$?
\item \emph{Effective bracket width.} Since $\Sigma(n,k)\sim k\binom{n}{\ffloor{n/2}}$ for fixed $k$, closing the bracket amounts to determining $\lim_n \La(n,P)/\binom{n}{\ffloor{n/2}}$, conjectured to be an integer for every $P$ and not known to exist in general.
\end{itemize}

\section{Summary of results}

\begin{center}
\begin{tabular}{ll}
\toprule
Statement & Result\\
\midrule
Weak antichain freeness & $\mathcal F$ weak $A_m$-free $\iff|\mathcal F|<m$; $\La(n,A_{m+1})=m$\\
Strong $A_2$ & $\LaS(n,A_2)=n+1$; gap $\LaS-\La=n$\\
Strong $A_3$ & $\LaS(n,A_3)=2n$, attained by two disjoint chains\\
