function CENTRAL_START(n, k):
    if k >= n: return 0
    return ceil((n - k) / 2)          # unique a with n <= 2a+k <= n+1

function SIGMA(n, k):
    a <- CENTRAL_START(n, k)
    top <- min(a + k, n + 1)
    if a >= top: return 0
    v <- C(n, a); total <- v
    for i from a to top - 2:
        v <- v * (n - i) / (i + 1)     # exact integer recurrence
        total <- total + v
    return total

function K_SPERNER_REPORT(n, k):
    exact     <- SIGMA(n, k)
    classical <- k * C(n, floor(n/2))
    return (exact, classical, 100 * (classical - exact) / classical)

