function CHAIN_TOP(p):                       # memoised
    return 1 + max({CHAIN_TOP(q) : q LESS p} u {0})

function HEIGHT():
    return max over p of CHAIN_TOP(p)                       # O(N^2)

function TALL_BUTTERFLY_HEIGHT():                            # O(N^3)
    best <- NONE
    for each unordered pair {p1, p2}:
        U <- { q : p1 LESS q and p2 LESS q }
        if |U| >= 2:
            m <- min(CHAIN_TOP(p1), CHAIN_TOP(p2)) - 1
            best <- max(best, m)
    return best

function BRACKET(n):
    h  <- HEIGHT();  m <- TALL_BUTTERFLY_HEIGHT()
    kl <- max(h - 1, 1)
    if m is not NONE: kl <- max(kl, m + 2)
    ku <- N - 1
    return [ SIGMA(n, kl), SIGMA(n, ku) ]

