"""Algorithm: the two-sided bracket for an arbitrary finite poset,
including the butterfly and tall-butterfly improvements of the lower end."""

from __future__ import annotations

from functools import lru_cache
from itertools import combinations
from math import comb
from typing import Dict, List, Optional, Set, Tuple


def central_start(n: int, k: int) -> int:
    if k >= n:
        return 0
    return -((n - k) // -2)


def sigma(n: int, k: int) -> int:
    a = central_start(n, k)
    return sum(comb(n, i) for i in range(a, min(a + k, n + 1)))


class FinitePoset:
    """A finite poset on {0, ..., N-1} given by its strict order relation."""

    def __init__(self, name: str, size: int, less: Set[Tuple[int, int]]) -> None:
        self.name = name
        self.size = size
        self.less = set(less)

    def lt(self, p: int, q: int) -> bool:
        return (p, q) in self.less

    @lru_cache(maxsize=None)
    def _chain_top(self, p: int) -> int:
        """Number of elements of the longest chain of P whose top is p."""
        best = 1
        for q in range(self.size):
            if self.lt(q, p):
                best = max(best, 1 + self._chain_top(q))
        return best

    def height(self) -> int:
        """h(P): the maximum number of elements of a chain in P.  O(N^2)."""
        return max(self._chain_top(p) for p in range(self.size))

    def tall_butterfly_height(self) -> Optional[int]:
        """Largest m with a tall butterfly of height m, or None if no butterfly.

        Scans all pairs (p1, p2) and their common strict upper sets: O(N^3).
        """
        best: Optional[int] = None
        for p1, p2 in combinations(range(self.size), 2):
            uppers = [q for q in range(self.size)
                      if self.lt(p1, q) and self.lt(p2, q)]
            if len(uppers) >= 2:
                m = min(self._chain_top(p1), self._chain_top(p2)) - 1
                best = m if best is None else max(best, m)
        return best

    def bracket(self, n: int) -> Dict[str, object]:
        """The interval containing La(n, P), with all three bounds."""
        h = self.height()
        m = self.tall_butterfly_height()
        k_height = max(h - 1, 1)
        k_local = k_height if m is None else max(k_height, m + 2)
        k_upper = self.size - 1
        return {
            "poset": self.name,
            "size": self.size,
            "height": h,
            "tall_butterfly_height": m,
            "lower_from_height": sigma(n, k_height),
            "lower_improved": sigma(n, k_local),
            "upper": sigma(n, k_upper) if k_upper <= n + 1 else None,
            "layers_lower": k_local,
            "layers_upper": k_upper,
        }


def chain(k: int) -> FinitePoset:
    return FinitePoset(f"chain C_{k}", k,
                       {(i, j) for i in range(k) for j in range(k) if i < j})


def boolean_lattice(d: int) -> FinitePoset:
    size = 1 << d
    less = {(x, y) for x in range(size) for y in range(size)
            if x != y and (x & y) == x}
    return FinitePoset(f"Boolean lattice B_{d}", size, less)


def butterfly() -> FinitePoset:
    return FinitePoset("butterfly", 4, {(0, 2), (0, 3), (1, 2), (1, 3)})


def antichain(m: int) -> FinitePoset:
    return FinitePoset(f"antichain A_{m}", m, set())


if __name__ == "__main__":
    n = 12
    posets: List[FinitePoset] = [chain(2), chain(4), antichain(3), butterfly(),
                                 boolean_lattice(2), boolean_lattice(3)]
    for P in posets:
        print(P.bracket(n))

