function LUBELL(n, F):
    return sum over A in F of Fraction(1, C(n, |A|))       # exact, O(|F|)

function MIRSKY_PEEL(F):
    levels <- []; R <- F
    while R nonempty:
        M <- { A in R : no B in R with A strictly contained in B }
        append M to levels; R <- R \ M
    return levels          # |levels| = height(F); each level is an antichain

function CERTIFICATE(n, F):
    k      <- |MIRSKY_PEEL(F)|
    weight <- LUBELL(n, F)                 # guaranteed <= k by LYM
    bound  <- SIGMA(n, k)                  # knapsack step
    return (k, weight, bound, |F| <= bound)
